insert into public.reading_templates (card_id, category_id, position, orientation, interpretation) values
  ('the-fool', 'relationship', 'general', 'upright', 'Hubungan baru atau babak baru dalam hubungan yang ada terasa ringan dan penuh kejutan. Terbukalah pada kemungkinan tanpa menuntut kepastian sejak hari pertama.'),
  ('the-fool', 'friendship', 'general', 'upright', 'Ada peluang berkenalan dengan orang baru, atau mengajak lingkaran lama mencoba hal yang belum pernah dilakukan bersama. Spontanitas kecil bisa menyegarkan pertemanan.'),
  ('the-fool', 'career', 'general', 'upright', 'Jalur baru, proyek perdana, atau pindah bidang sedang memanggil. Kamu belum perlu punya semua jawabannya; mulailah sebagai pemula yang mau belajar.'),
  ('the-fool', 'finance', 'general', 'upright', 'Peluang finansial baru bisa muncul, tetapi antusiasme perlu disertai batas yang jelas. Sisihkan dulu dana aman sebelum mencoba sesuatu yang belum teruji.'),
  ('the-fool', 'family', 'general', 'upright', 'Untuk urusan keluarga, kartu ini menonjolkan awal baru serta spontanitas. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('the-fool', 'self-discovery', 'general', 'upright', 'Kamu diajak melepas peran lama dan bertanya, siapa aku jika tidak harus tampil sempurna? Kepolosanmu masih menjadi kompas yang layak dipercaya.'),
  ('the-fool', 'personal-growth', 'general', 'upright', 'Dalam perjalanan berkembang, kartu ini menonjolkan awal baru serta spontanitas. Kemajuanmu mungkin lebih besar dari yang kamu sadari; akui itu.'),
  ('the-fool', 'life-decisions', 'general', 'upright', 'Di persimpangan keputusan, energi awal baru dan spontanitas terasa terbuka. Uji dulu dengan langkah kecil sebelum komitmen besar.'),
  ('the-fool', 'relationship', 'general', 'reversed', 'Ada kecenderungan melompat ke hubungan tanpa melihat siapa orangnya, atau sebaliknya menutup diri karena takut mengulang luka. Pelan-pelan saja: kenali dulu, baru putuskan seberapa jauh melangkah.'),
  ('the-fool', 'friendship', 'general', 'reversed', 'Ajakan atau rencana bersama bisa terdengar menarik tetapi kurang matang. Perhatikan apakah kamu atau temanmu sedang bertindak impulsif, atau justru terlalu ragu untuk membuka diri.'),
  ('the-fool', 'career', 'general', 'reversed', 'Hati-hati dengan keputusan kerja yang diambil karena bosan atau emosi sesaat. Di sisi lain, jangan terus menunda langkah yang sebenarnya sudah kamu siapkan.'),
  ('the-fool', 'finance', 'general', 'reversed', 'Pengeluaran spontan atau taruhan tanpa perhitungan perlu dihindari. Tinjau ulang rencana keuanganmu dan pastikan ada jaring pengaman sebelum mengambil risiko baru.'),
  ('the-fool', 'family', 'general', 'reversed', 'Untuk urusan keluarga, ceroboh dan ragu melangkah bisa terasa berat. Kamu tidak harus menyelesaikan semuanya sekaligus; satu percakapan jujur sudah merupakan awal.'),
  ('the-fool', 'self-discovery', 'general', 'reversed', 'Rasa takut salah membuatmu menahan diri, atau justru kamu lari dari kenyataan lewat tindakan yang tergesa. Tanyakan apa yang sebenarnya sedang kamu hindari.'),
  ('the-fool', 'personal-growth', 'general', 'reversed', 'Di jalur pertumbuhan, ceroboh dan ragu melangkah terasa menantang. Pecah tujuan menjadi langkah yang cukup kecil untuk dijalani hari ini.'),
  ('the-fool', 'life-decisions', 'general', 'reversed', 'Dalam menimbang pilihan, kartu ini menyorot ceroboh serta ragu melangkah sebagai hal yang perlu dipertimbangkan lebih matang sebelum melangkah.'),
  ('the-magician', 'relationship', 'general', 'upright', 'Daya tarik dan komunikasi yang jelas membuka pintu. Ungkapkan niatmu dengan terang, dan tunjukkan perhatian lewat tindakan nyata, bukan sekadar kata.'),
  ('the-magician', 'friendship', 'general', 'upright', 'Kamu punya kemampuan menghubungkan orang dan memulai sesuatu. Gunakan inisiatif itu untuk mengajak, menghubungi, atau menyatukan lingkaran pertemananmu.'),
  ('the-magician', 'career', 'general', 'upright', 'Keterampilan dan relasimu cukup untuk memulai proyek atau menawarkan gagasan. Ini waktu yang baik untuk tampil, mempresentasikan, dan memegang kendali atas alurmu.'),
  ('the-magician', 'finance', 'general', 'upright', 'Sumber daya yang kamu butuhkan mungkin sudah ada, hanya perlu ditata. Rencanakan dengan sadar dan gunakan keahlianmu untuk membuka sumber penghasilan.'),
  ('the-magician', 'family', 'general', 'upright', 'Untuk urusan keluarga, kartu ini menonjolkan kemauan serta manifestasi. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('the-magician', 'self-discovery', 'general', 'upright', 'Kamu diingatkan bahwa kemauan batinmu nyata. Saat pikiran, perasaan, dan tindakan searah, hal yang tadinya terasa mustahil menjadi mungkin.'),
  ('the-magician', 'personal-growth', 'general', 'upright', 'Dalam perjalanan berkembang, kartu ini menonjolkan kemauan serta manifestasi. Kemajuanmu mungkin lebih besar dari yang kamu sadari; akui itu.'),
  ('the-magician', 'life-decisions', 'general', 'upright', 'Di persimpangan keputusan, energi kemauan dan manifestasi terasa terbuka. Uji dulu dengan langkah kecil sebelum komitmen besar.'),
  ('the-magician', 'relationship', 'general', 'reversed', 'Ada risiko kata-kata manis yang tidak sejalan dengan perbuatan, dari pihak mana pun. Pastikan kejujuran dan konsistensi sebelum menaruh harapan terlalu besar.'),
  ('the-magician', 'friendship', 'general', 'reversed', 'Janji yang terdengar meyakinkan belum tentu ditepati, atau kamu sendiri belum sepenuhnya terbuka. Dorong keterusterangan agar kepercayaan tidak retak.'),
  ('the-magician', 'career', 'general', 'reversed', 'Bakatmu belum tersalurkan, atau ada tekanan untuk tampil lebih dari kenyataan. Fokus pada satu proyek yang bisa kamu selesaikan, dan waspadai pihak yang menjanjikan jalan pintas.'),
  ('the-magician', 'finance', 'general', 'reversed', 'Waspadai tawaran yang terdengar terlalu mudah dan pengelolaan uang yang tidak transparan. Periksa detailnya sebelum menyetujui apa pun.'),
  ('the-magician', 'family', 'general', 'reversed', 'Di lingkup keluarga, kartu ini menyorot manipulasi serta bakat tersia-sia, tanda adanya ketegangan atau beban yang belum terucap. Mulailah dari mendengarkan, bukan membela diri.'),
  ('the-magician', 'self-discovery', 'general', 'reversed', 'Potensimu tertahan oleh ragu atau perhatian yang terpecah. Jujurlah pada dirimu tentang apa yang sebenarnya ingin kamu ciptakan.'),
  ('the-magician', 'personal-growth', 'general', 'reversed', 'Untuk pertumbuhan pribadi, manipulasi dan bakat tersia-sia menunjuk pada pola lama yang perlu dilihat dengan jujur. Bersikaplah lembut pada diri sendiri sambil tetap mencoba satu perubahan kecil.'),
  ('the-magician', 'life-decisions', 'general', 'reversed', 'Dalam menimbang pilihan, kartu ini menyorot manipulasi serta bakat tersia-sia sebagai hal yang perlu dipertimbangkan lebih matang sebelum melangkah.'),
  ('the-high-priestess', 'relationship', 'general', 'upright', 'Ada lapisan perasaan yang belum dibicarakan, dan kepekaan akan banyak membantu. Dengarkan firasatmu tentang orang itu, dan beri ruang agar kejujuran muncul dengan sendirinya.'),
  ('the-high-priestess', 'friendship', 'general', 'upright', 'Seseorang di lingkaranmu mungkin menyimpan sesuatu yang belum dibagikan. Kepekaanmu lebih berguna daripada menginterogasi; hadirlah dan dengarkan.'),
  ('the-high-priestess', 'career', 'general', 'upright', 'Belum semua informasi terlihat. Amati dinamika, kumpulkan data, dan percayai penilaian diam-diammu sebelum mengambil sikap terbuka.'),
  ('the-high-priestess', 'finance', 'general', 'upright', 'Ada faktor yang belum kamu ketahui soal uang atau sumber daya. Teliti dulu dan tahan keputusan besar sampai gambarannya utuh.'),
  ('the-high-priestess', 'family', 'general', 'upright', 'Untuk urusan keluarga, kartu ini menonjolkan intuisi serta rahasia. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('the-high-priestess', 'self-discovery', 'general', 'upright', 'Suara batinmu sedang berbicara lewat mimpi, simbol, dan firasat. Menyendiri dengan tenang adalah cara terbaik untuk mengenalinya.'),
  ('the-high-priestess', 'personal-growth', 'general', 'upright', 'Dalam perjalanan berkembang, kartu ini menonjolkan intuisi serta rahasia. Kemajuanmu mungkin lebih besar dari yang kamu sadari; akui itu.'),
  ('the-high-priestess', 'life-decisions', 'general', 'upright', 'Dalam menimbang pilihan, kartu ini menonjolkan intuisi serta rahasia. Pilihan yang selaras dengan nilai-nilaimu cenderung terasa lebih mantap.'),
  ('the-high-priestess', 'relationship', 'general', 'reversed', 'Ada sesuatu yang dipendam atau tidak terucap, dan itu menciptakan jarak. Hindari menebak-nebak sendiri; undang percakapan yang lembut tetapi jujur.'),
  ('the-high-priestess', 'friendship', 'general', 'reversed', 'Kabar burung atau asumsi bisa mengaburkan keadaan sebenarnya. Cek langsung pada orangnya sebelum menarik kesimpulan.'),
  ('the-high-priestess', 'career', 'general', 'reversed', 'Kamu mungkin mengabaikan firasat yang sebenarnya penting, atau ada informasi yang sengaja disembunyikan. Cari fakta tambahan sebelum memutuskan.'),
  ('the-high-priestess', 'finance', 'general', 'reversed', 'Kurangnya transparansi atau kabut soal angka membuat keputusan sulit. Minta penjelasan tertulis dan jangan bertindak atas dugaan semata.'),
  ('the-high-priestess', 'family', 'general', 'reversed', 'Untuk urusan keluarga, tema mengabaikan intuisi dan rahasia tersembunyi muncul tanpa arah yang tegas. Amati dinamika yang ada dan beri ruang bagi setiap pihak untuk bicara.'),
  ('the-high-priestess', 'self-discovery', 'general', 'reversed', 'Intuisimu tertimbun oleh pikiran yang terlalu ramai. Kembali ke tubuh dan napas, lalu tanyakan apa yang sebenarnya sudah kamu ketahui.'),
  ('the-high-priestess', 'personal-growth', 'general', 'reversed', 'Untuk proses berkembang, tema mengabaikan intuisi dan rahasia tersembunyi hadir sebagai bahan refleksi. Catat apa yang berulang, lalu pilih satu hal untuk dicoba berbeda.'),
  ('the-high-priestess', 'life-decisions', 'general', 'reversed', 'Dalam menimbang pilihan, tema mengabaikan intuisi dan rahasia tersembunyi muncul seimbang. Tuliskan untung-rugi tiap opsi dan lihat mana yang paling selaras denganmu.'),
  ('the-empress', 'relationship', 'general', 'upright', 'Kehangatan, kemesraan, dan rasa aman tumbuh di antara kalian. Nikmati kebersamaan, perhatikan kebutuhan sederhana pasangan, dan biarkan kasih berkembang dengan sabar.'),
  ('the-empress', 'friendship', 'general', 'upright', 'Persahabatan yang menenangkan dan saling merawat. Berbagi makanan, cerita, atau kreativitas bersama memperkuat ikatan.'),
  ('the-empress', 'career', 'general', 'upright', 'Proyek kreatif atau lingkungan kerja yang subur memberi hasil. Gagasan yang dirawat dengan telaten mulai menunjukkan buah.'),
  ('the-empress', 'finance', 'general', 'upright', 'Kelimpahan dan kenyamanan material meningkat. Nikmati hasil kerja, dan tetap atur supaya yang berlimpah tidak menguap begitu saja.'),
  ('the-empress', 'family', 'general', 'upright', 'Untuk urusan keluarga, kartu ini menonjolkan kesuburan serta pengasuhan. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('the-empress', 'self-discovery', 'general', 'upright', 'Kamu diajak lebih lembut pada tubuh dan perasaanmu. Keindahan, alam, dan kenyamanan bukan kemewahan melainkan makanan bagi jiwa.'),
  ('the-empress', 'personal-growth', 'general', 'upright', 'Dalam perjalanan berkembang, kartu ini menonjolkan kesuburan serta pengasuhan. Kemajuanmu mungkin lebih besar dari yang kamu sadari; akui itu.'),
  ('the-empress', 'life-decisions', 'general', 'upright', 'Di persimpangan keputusan, energi kesuburan dan pengasuhan terasa terbuka. Uji dulu dengan langkah kecil sebelum komitmen besar.'),
  ('the-empress', 'relationship', 'general', 'reversed', 'Perhatian bisa berubah menjadi ketergantungan atau kontrol halus. Seimbangkan memberi dan menerima, dan hormati ruang masing-masing.'),
  ('the-empress', 'friendship', 'general', 'reversed', 'Ada kecenderungan menjadi pengasuh yang kelelahan, atau sebaliknya bergantung pada teman. Tetapkan batas yang sehat agar kasih tidak berubah jadi beban.'),
  ('the-empress', 'career', 'general', 'reversed', 'Kreativitas tersendat atau kerja keras tidak diimbangi istirahat. Beri ruang pada ide untuk tumbuh, dan jangan abaikan kebutuhan dasarmu.'),
  ('the-empress', 'finance', 'general', 'reversed', 'Pengeluaran demi kenyamanan bisa melebihi anggaran, atau hasil jerih payah terasa seret. Tinjau kebiasaan belanja dan ruang pemasukanmu.'),
  ('the-empress', 'family', 'general', 'reversed', 'Untuk urusan keluarga, ketergantungan dan mengabaikan diri bisa terasa berat. Kamu tidak harus menyelesaikan semuanya sekaligus; satu percakapan jujur sudah merupakan awal.'),
  ('the-empress', 'self-discovery', 'general', 'reversed', 'Kamu mungkin mengabaikan kebutuhanmu sendiri demi orang lain. Pulihkan diri dulu: tidur, makan baik, dan waktu menyendiri.'),
  ('the-empress', 'personal-growth', 'general', 'reversed', 'Untuk pertumbuhan pribadi, ketergantungan dan mengabaikan diri menunjuk pada pola lama yang perlu dilihat dengan jujur. Bersikaplah lembut pada diri sendiri sambil tetap mencoba satu perubahan kecil.'),
  ('the-empress', 'life-decisions', 'general', 'reversed', 'Di persimpangan keputusan, ketergantungan dan mengabaikan diri terasa berat. Beri jarak sejenak, lalu kembali dengan kepala yang lebih tenang.'),
  ('the-emperor', 'relationship', 'general', 'upright', 'Kestabilan dan komitmen menjadi fondasi. Kejelasan harapan dan sikap bertanggung jawab membuat hubungan terasa aman.'),
  ('the-emperor', 'friendship', 'general', 'upright', 'Seseorang berperan sebagai penopang atau pengatur dalam kelompok. Aturan main yang jelas membantu pertemanan berjalan sehat.'),
  ('the-emperor', 'career', 'general', 'upright', 'Kepemimpinan, struktur, dan kerja terorganisir membawa kemajuan. Ambil tanggung jawab dan tetapkan sistem yang bisa diandalkan.'),
  ('the-emperor', 'finance', 'general', 'upright', 'Anggaran yang tertata dan keputusan keuangan yang tegas menciptakan rasa aman. Disiplin kecil yang berulang lebih berarti dari lonjakan sesaat.'),
  ('the-emperor', 'family', 'general', 'upright', 'Dalam hubungan keluarga, struktur dan otoritas menjadi nada utama. Suasananya cenderung mendukung untuk mempererat ikatan lewat obrolan yang tulus dan waktu bersama.'),
  ('the-emperor', 'self-discovery', 'general', 'upright', 'Kamu diajak membangun batas dan rutinitas yang sehat. Bagian dirimu yang bertanggung jawab siap memegang kemudi.'),
  ('the-emperor', 'personal-growth', 'general', 'upright', 'Untuk pertumbuhan pribadi, struktur dan otoritas menunjukkan momentum yang baik. Pilih satu kebiasaan kecil yang selaras dengan arah ini dan jalani secara konsisten.'),
  ('the-emperor', 'life-decisions', 'general', 'upright', 'Dalam menimbang pilihan, kartu ini menonjolkan struktur serta otoritas. Pilihan yang selaras dengan nilai-nilaimu cenderung terasa lebih mantap.'),
  ('the-emperor', 'relationship', 'general', 'reversed', 'Sikap mendominasi atau kekakuan dapat membuat pasangan merasa tidak didengar. Tanyakan apakah kamu mengontrol demi rasa aman, bukan karena kebutuhan nyata.'),
  ('the-emperor', 'friendship', 'general', 'reversed', 'Aturan atau ego bisa merusak kebersamaan. Beri ruang bagi suara teman, dan hindari memaksakan caramu.'),
  ('the-emperor', 'career', 'general', 'reversed', 'Atasan yang kaku, birokrasi yang menjerat, atau kurangnya struktur membuat kerja tersendat. Cari keseimbangan antara aturan dan fleksibilitas.'),
  ('the-emperor', 'finance', 'general', 'reversed', 'Pengelolaan uang yang longgar atau kontrol berlebihan membuat suasana tegang. Buat sistem sederhana yang adil dan bisa diikuti.'),
  ('the-emperor', 'family', 'general', 'reversed', 'Di lingkup keluarga, kartu ini menyorot kaku serta dominasi, tanda adanya ketegangan atau beban yang belum terucap. Mulailah dari mendengarkan, bukan membela diri.'),
  ('the-emperor', 'self-discovery', 'general', 'reversed', 'Kamu mungkin keras pada diri sendiri, atau sebaliknya sulit menegakkan disiplin. Cari bentuk struktur yang melindungi, bukan mengurung.'),
  ('the-emperor', 'personal-growth', 'general', 'reversed', 'Di jalur pertumbuhan, kaku dan dominasi terasa menantang. Pecah tujuan menjadi langkah yang cukup kecil untuk dijalani hari ini.'),
  ('the-emperor', 'life-decisions', 'general', 'reversed', 'Untuk keputusan hidup, kaku dan dominasi mengingatkan agar tidak tergesa-gesa. Periksa ulang asumsimu dan cari pandangan dari orang yang kamu percaya.'),
  ('the-hierophant', 'relationship', 'general', 'upright', 'Komitmen mengikuti nilai bersama, entah lewat pernikahan, janji, atau kesepakatan jelas. Kesamaan prinsip memperkuat kedekatan.'),
  ('the-hierophant', 'friendship', 'general', 'upright', 'Komunitas, kelompok belajar, atau tradisi bersama mengikat pertemanan. Menghormati kebiasaan kelompok membantu kamu diterima.'),
  ('the-hierophant', 'career', 'general', 'upright', 'Jalur formal, pelatihan, atau mentor membantu kemajuan karier. Ikuti prosedur yang berlaku sambil belajar dari yang berpengalaman.'),
  ('the-hierophant', 'finance', 'general', 'upright', 'Pendekatan konvensional dan penasihat tepercaya menguntungkan. Metode yang sudah teruji lebih aman daripada eksperimen.'),
  ('the-hierophant', 'family', 'general', 'upright', 'Di lingkup keluarga, energi tradisi dan bimbingan terasa kuat. Manfaatkan untuk membangun kebiasaan kecil yang menghangatkan rumah.'),
  ('the-hierophant', 'self-discovery', 'general', 'upright', 'Kamu mencari makna lewat ajaran, ritual, atau guru. Hormati warisan yang menguatkanmu sambil tetap jujur pada keyakinanmu.'),
  ('the-hierophant', 'personal-growth', 'general', 'upright', 'Di jalur pertumbuhan, energi tradisi dan bimbingan mendukung. Ini saat yang baik untuk mencoba hal baru dalam langkah yang terukur.'),
  ('the-hierophant', 'life-decisions', 'general', 'upright', 'Di persimpangan keputusan, energi tradisi dan bimbingan terasa terbuka. Uji dulu dengan langkah kecil sebelum komitmen besar.'),
  ('the-hierophant', 'relationship', 'general', 'reversed', 'Harapan sosial atau aturan tradisional menekan hubungan. Bicarakan secara terbuka bentuk kebersamaan yang cocok untuk kalian berdua.'),
  ('the-hierophant', 'friendship', 'general', 'reversed', 'Tekanan untuk menyesuaikan diri dengan kelompok membuatmu tidak nyaman. Tidak apa-apa memilih jalan yang sedikit berbeda.'),
  ('the-hierophant', 'career', 'general', 'reversed', 'Aturan kantor yang kaku atau lingkungan yang menolak gagasan baru bisa menghambat. Pertimbangkan cara halus untuk memperbarui sistem.'),
  ('the-hierophant', 'finance', 'general', 'reversed', 'Ketergantungan pada nasihat yang tidak lagi relevan, atau menolak semua saran. Pilih pendekatan yang sesuai situasimu, bukan sekadar mengikuti tren atau kebiasaan.'),
  ('the-hierophant', 'family', 'general', 'reversed', 'Dalam keluarga, dogma dan memberontak sedang bergerak pelan. Tidak perlu terburu-buru; konsistensi kecil lebih berarti daripada keputusan besar.'),
  ('the-hierophant', 'self-discovery', 'general', 'reversed', 'Kamu sedang mempertanyakan keyakinan yang diwariskan. Itu proses yang sah; yang penting menemukan nilai yang terasa jujur di dalam.'),
  ('the-hierophant', 'personal-growth', 'general', 'reversed', 'Dalam pertumbuhan pribadi, kartu ini menyoroti dogma dan memberontak. Fase ini lebih tentang mengamati pola diri daripada mengejar hasil.'),
  ('the-hierophant', 'life-decisions', 'general', 'reversed', 'Di persimpangan keputusan, dogma dan memberontak menandakan fase menimbang. Tidak memutuskan hari ini pun bisa menjadi keputusan yang sah.'),
  ('the-lovers', 'relationship', 'general', 'upright', 'Ada koneksi mendalam yang didasari kejujuran dan saling memilih. Hubungan tumbuh ketika dua orang berani terbuka dan sejalan dalam nilai.'),
  ('the-lovers', 'friendship', 'general', 'upright', 'Persahabatan yang jujur dan selaras nilai. Kamu mungkin juga diminta memilih lingkaran yang mencerminkan dirimu.'),
  ('the-lovers', 'career', 'general', 'upright', 'Pilihan karier yang sesuai passion dan nilai, atau kemitraan kerja yang harmonis. Ikuti yang membuat dirimu merasa utuh.'),
  ('the-lovers', 'finance', 'general', 'upright', 'Keputusan keuangan sebaiknya selaras dengan nilai, bukan sekadar angka. Diskusikan secara terbuka bila ada pihak lain yang terlibat.'),
  ('the-lovers', 'family', 'general', 'upright', 'Untuk urusan keluarga, kartu ini menonjolkan cinta serta pilihan sadar. Ini bisa menjadi saat yang baik untuk menyampaikan apresiasi atau meluruskan kesalahpahaman lama.'),
  ('the-lovers', 'self-discovery', 'general', 'upright', 'Kamu menyelaraskan sisi sadar dan batinmu. Mengakui keinginan dan nilai yang sebenarnya adalah langkah menuju keutuhan.'),
  ('the-lovers', 'personal-growth', 'general', 'upright', 'Dalam perjalanan berkembang, kartu ini menonjolkan cinta serta pilihan sadar. Kemajuanmu mungkin lebih besar dari yang kamu sadari; akui itu.'),
  ('the-lovers', 'life-decisions', 'general', 'upright', 'Di persimpangan keputusan, energi cinta dan pilihan sadar terasa terbuka. Uji dulu dengan langkah kecil sebelum komitmen besar.'),
  ('the-lovers', 'relationship', 'general', 'reversed', 'Ada jarak, kesalahpahaman, atau godaan yang menguji komitmen. Bicarakan apa adanya agar kedua pihak tahu posisi satu sama lain.'),
  ('the-lovers', 'friendship', 'general', 'reversed', 'Nilai atau kepentingan yang berbeda mulai terasa dalam pertemanan. Jujur namun lembut dapat mencegah renggang lebih jauh.'),
  ('the-lovers', 'career', 'general', 'reversed', 'Tawaran atau pekerjaan yang bertentangan dengan nilaimu menimbulkan konflik batin. Evaluasi ulang sebelum menyesal.'),
